// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract SelectorRecorder {
    uint256 public calls;
    bytes4 public lastSelector;
    uint256 public lastValue;

    function transferFrom(address, address, uint256) external payable returns (bool) {
        calls++;
        lastSelector = msg.sig;
        lastValue = msg.value;
        return true;
    }
}

contract InvMutTest is Test {
    airPort c;

    function setUp() public {
        c = new airPort();
    }

    function testFuzz_property(uint256 n, address from, uint256 v) public {
        n = bound(n, 1, 16);
        address[] memory tos = new address[](n);
        for (uint256 i = 0; i < n; i++) {
            tos[i] = address(uint160(uint256(keccak256(abi.encode(i, from, v)))));
        }
        SelectorRecorder rec = new SelectorRecorder();
        vm.prank(from);
        bool ok; try c.transfer(from, address(rec), tos, v) { ok = true; } catch { ok = false; }
        assertTrue(ok && rec.calls() == n && rec.lastSelector() == bytes4(keccak256("transferFrom(address,address,uint256)")));
    }
}
